# xml2::xml_validate (libxml2's XML Schema validator) over the built-in datatypes, facets, lists and
# unions, and over content models (sequence, choice, all, occurrence, attributes, mixed content,
# extension and restriction, ID and IDREF, xsi:nil). A case holds the schema and the instance ("in")
# and R's verdict, TRUE or FALSE.
library(xml2)

xs <- 'xmlns:xs="http://www.w3.org/2001/XMLSchema"'
esc <- function(s) gsub(">", "&gt;", gsub("<", "&lt;", gsub("&", "&amp;", s, fixed = TRUE), fixed = TRUE), fixed = TRUE)
verdict <- function(schema, instance) {
  r <- tryCatch(suppressWarnings(xml_validate(read_xml(instance), read_xml(schema))), error = function(e) "ERR")
  if (identical(r, "ERR")) "ERR" else if (isTRUE(r)) "TRUE" else "FALSE"
}
cases <- list()
add <- function(schema, instance) cases[[length(cases) + 1]] <<- case("validate", numeric(0), verdict(schema, instance), input = c(schema, instance))

# value tests: one element v of a type, many text values
value_tests <- function(type_xml, values) {
  schema <- sprintf('<xs:schema %s><xs:element name="v">%s</xs:element></xs:schema>', xs, type_xml)
  for (v in values) add(schema, sprintf("<v>%s</v>", esc(v)))
}
builtin <- function(t, values) value_tests(sprintf('<xs:complexType><xs:simpleContent><xs:extension base="xs:%s"/></xs:simpleContent></xs:complexType>', t), values)
builtin2 <- function(t, values) {
  schema <- sprintf('<xs:schema %s><xs:element name="v" type="xs:%s"/></xs:schema>', xs, t)
  for (v in values) add(schema, sprintf("<v>%s</v>", esc(v)))
}
