for (t in c("integer", "int", "short", "byte", "long", "unsignedByte", "unsignedShort", "unsignedInt", "unsignedLong", "positiveInteger", "negativeInteger", "nonNegativeInteger", "nonPositiveInteger")) builtin2(t, ints)
