# Cases that libxml2 judges by its own rules: QName values resolved against the in-scope namespace
# declarations, NOTATION, and ordered facets on a value with a time zone against a bound without one
# (compared as UTC instants; equal is undecided, so invalid). Left out: xs:time with an offset (libxml2
# normalises it wrongly), base64 "-_-_" (accepted by libxml2) and maxOccurs="0".
qs <- sprintf('<xs:schema %s><xs:element name="v" type="xs:QName"/></xs:schema>', xs)
for (inst in c('<v xmlns:p="u">p:a</v>', '<v>p:a</v>', '<v xmlns="u">a</v>', '<v>a</v>', '<v>:a</v>', '<v xmlns:p="u">p:</v>', '<v xmlns:p="u"> p:a </v>', '<v xmlns:p="u">p:a:b</v>', '<v xmlns:xml2="u">xml:lang</v>', '<v>xml:lang</v>', '<v xmlns:p="u">1p:a</v>', '<v></v>')) add(qs, inst)
ns_schema <- sprintf('<xs:schema %s><xs:notation name="n" public="x"/><xs:element name="v"><xs:simpleType><xs:restriction base="xs:NOTATION"><xs:enumeration value="n"/></xs:restriction></xs:simpleType></xs:element></xs:schema>', xs)
for (inst in c("<v>n</v>", "<v>m</v>", "<v></v>")) add(ns_schema, inst)
builtin2("base64Binary", c("AA_A", "AA-A", "AA+/", "AAA/", "A+/="))
for (b in c("2000-01-01", "2000-01-01Z", "2000-01-01+05:00")) {
  value_tests(restr("date", c(f("minInclusive", b))), c("1999-12-31", "2000-01-01", "2000-01-02", "1999-12-31Z", "2000-01-01Z", "2000-01-01+14:00", "2000-01-02-05:00", "1999-12-31+14:00"))
  value_tests(restr("dateTime", c(f("maxExclusive", sub("^(.{10})", "\\1T00:00:00", b)))), c("1999-12-31T23:59:59", "2000-01-01T00:00:00", "1999-12-31T23:59:59Z", "2000-01-01T00:00:00Z", "2000-01-01T00:00:00+05:00"))
}

# A facet bound that is not a value of the type: libxml2 answers FALSE (it does not raise).
for (bad in list(c("dateTime", "minInclusive", "2000-01-01+05:00T00:00:00", "2001-01-01T00:00:00"), c("int", "minInclusive", "abc", "5"), c("date", "maxInclusive", "x", "2000-01-01"), c("decimal", "minInclusive", "1.2.3", "1"))) {
  add(sprintf('<xs:schema %s><xs:element name="v"><xs:simpleType><xs:restriction base="xs:%s"><xs:%s value="%s"/></xs:restriction></xs:simpleType></xs:element></xs:schema>', xs, bad[1], bad[2], bad[3]), sprintf("<v>%s</v>", bad[4]))
}

emit("xml2_xsd", "xml2", list(cases))
